-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'Oficinas de Impressão 3D e Robótica' and a.numero = 9
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 9 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 09', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 09 (10 questões discursivas)',
      '/MATERIAIS/RIO_DO_SUL_MAIS_TECH/OFICINAS_IMPRESSAO_3D_ROBOTICA/ATIVIDADES/ATIVIDADE-PRATICA-AULA-09.html', 10, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Liste, na ordem, as cinco partes de uma boa apresentação de projeto.', 0.3, '1) Problema; 2) Solução; 3) Processo; 4) Resultado (demonstração ao vivo do protótipo); 5) Melhorias.', 'Nota cheia: as cinco partes na ordem certa. Metade: as cinco partes com a ordem trocada, ou quatro na ordem certa. Zero: três ou menos.'),
      (v_atividade, 1, 2, 'Explique o que a equipe deve dizer nas partes Problema e Solução.', 0.3, 'Em Problema, dizer o que o robô precisava resolver. Em Solução, mostrar a peça impressa e explicar como ela ajuda o robô a resolver o problema.', 'Nota cheia: explica corretamente as duas partes. Metade: explica só uma ou as duas de forma vaga. Zero: sem relação.'),
      (v_atividade, 1, 3, 'Explique o que a equipe deve mostrar nas partes Processo e Melhorias.', 0.4, 'Em Processo, contar a modelagem, o fatiamento, a impressão, a montagem, o programa e os testes, com as falhas e as correções. Em Melhorias, dizer o que a equipe faria na próxima versão.', 'Nota cheia: explica as duas partes com as etapas do processo e as melhorias da próxima versão. Metade: explica corretamente só uma. Zero: sem relação.'),
      (v_atividade, 2, 1, 'Indique quanto tempo cada equipe tem para apresentar.', 0.3, 'Cada equipe tem de 5 a 7 minutos (até 7 minutos).', 'Nota cheia: informa o tempo de 5 a 7 minutos (aceita "até 7 minutos"). Metade: tempo aproximado errado, mas fala em poucos minutos por equipe. Zero: tempo muito diferente ou em branco.'),
      (v_atividade, 2, 2, 'Cite os dois momentos que acontecem antes das apresentações e diga o que cada um faz.', 0.3, 'Abertura e organização (15 min): combinar a ordem das apresentações e os critérios. Ensaio e ajustes finais (30 min): última conferência dos protótipos.', 'Nota cheia: cita os dois momentos e a função de cada um. Metade: cita os dois sem a função, ou só um com a função. Zero: sem relação.'),
      (v_atividade, 2, 3, 'Diga quando acontecem o feedback da turma com a autoavaliação e o fechamento da UC, e explique por que é importante guardar tempo para eles.', 0.4, 'O feedback da turma e a autoavaliação (40 min) e o fechamento da UC (20 min) acontecem depois dos dois blocos de apresentações. É importante reservar tempo para refletir sobre pontos fortes e melhorias, aprender com os colegas e encerrar a UC com a síntese.', 'Nota cheia: situa os momentos depois das apresentações e justifica a importância. Metade: só situa os momentos ou só justifica. Zero: sem relação.'),
      (v_atividade, 3, 1, 'Liste as etapas do processo que a equipe deve mostrar, da modelagem até os testes.', 0.3, 'Modelagem, fatiamento, impressão, montagem, programa (programação do robô) e testes.', 'Nota cheia: cita pelo menos cinco das seis etapas. Metade: três ou quatro. Zero: duas ou menos.'),
      (v_atividade, 3, 2, 'Explique por que a equipe deve mostrar também as falhas e as correções.', 0.3, 'Porque o processo inclui falhas e correções; mostrar o que deu errado e como foi resolvido prova o aprendizado, a tomada de decisão e a qualidade do projeto, e ajuda a turma a aprender.', 'Nota cheia: justifica com aprendizado ou decisões tomadas a partir das falhas. Metade: justificativa vaga, sem relação com o processo. Zero: diz que se deve esconder as falhas ou em branco.'),
      (v_atividade, 3, 3, 'Dê um exemplo de falha na peça impressa e diga qual princípio de design (espessura de paredes, suportes ou orientação) a equipe ajustou para corrigi-la.', 0.4, 'Exemplos: a peça quebrou por ter parede muito fina, então a equipe aumentou a espessura das paredes; a peça saiu com falhas nos trechos suspensos, então a equipe usou suportes; a peça ficou frágil na direção das camadas, então a equipe mudou a orientação de impressão.', 'Nota cheia: falha coerente com um dos três princípios e a correção correspondente. Metade: falha ou correção coerente, sem ligar ao princípio. Zero: sem relação com o design para impressão.'),
      (v_atividade, 4, 1, 'Explique o que significa ter um plano B para a demonstração.', 0.3, 'É ter uma alternativa pronta caso a demonstração ao vivo falhe, por exemplo um vídeo curto do robô funcionando.', 'Nota cheia: explica que é uma alternativa à demonstração e cita o vídeo curto. Metade: explica a ideia sem citar o vídeo. Zero: sem relação.'),
      (v_atividade, 4, 2, 'Escreva o que a equipe deve dizer à turma nessa situação, usando o plano B.', 0.3, 'Exemplo: "Nosso programa não carregou agora, mas temos um vídeo curto do robô funcionando para mostrar o resultado e vamos explicar o que aconteceu."', 'Nota cheia: texto calmo e claro que informa a falha e passa ao plano B. Metade: informa a falha sem usar o plano B. Zero: não escreve a fala ou culpa pessoas.'),
      (v_atividade, 4, 3, 'Cite duas preparações que a equipe poderia ter feito antes, no momento de ensaio e ajustes finais, para evitar o problema.', 0.4, 'Exemplos: testar o robô e o programa por completo; conferir se o programa carrega; gravar o vídeo do plano B; conferir os protótipos e as conexões.', 'Nota cheia: duas preparações coerentes com o ensaio e os ajustes finais. Metade: uma. Zero: nenhuma coerente.'),
      (v_atividade, 5, 1, 'Liste os quatro itens que a equipe deve documentar.', 0.3, 'Fotos do processo, captura do programa em blocos, arquivo STL e configurações do fatiador.', 'Nota cheia: os quatro itens. Metade: dois ou três. Zero: um ou nenhum.'),
      (v_atividade, 5, 2, 'Explique para que servem o arquivo STL e as configurações do fatiador na documentação.', 0.3, 'O STL é o modelo 3D da peça, que permite imprimi-la de novo igual; as configurações do fatiador registram como ela foi preparada para imprimir, permitindo repetir o resultado.', 'Nota cheia: explica a função dos dois. Metade: só um. Zero: sem relação.'),
      (v_atividade, 5, 3, 'Explique para que servem as fotos do processo e a captura do programa em blocos.', 0.4, 'As fotos registram as etapas e as falhas do processo; a captura do programa em blocos mostra como o robô foi programado, permitindo que outra equipe reproduza ou melhore.', 'Nota cheia: explica a função dos dois. Metade: só um. Zero: sem relação.'),
      (v_atividade, 6, 1, 'Diga qual é a regra da aula sobre a participação dos integrantes na apresentação.', 0.3, 'Todos os integrantes falam, e cada um explica a parte em que atuou.', 'Nota cheia: cita que todos falam e que cada um explica a sua parte. Metade: cita só um dos dois. Zero: sem relação.'),
      (v_atividade, 6, 2, 'Proponha como os quatro integrantes poderiam dividir a fala, indicando a parte do projeto que cada um explica.', 0.3, 'Exemplo: um integrante explica o problema e a solução; outro, a modelagem e a impressão da peça; outro, a montagem e o programa; outro, os testes, a demonstração e as melhorias.', 'Nota cheia: as quatro partes divididas, ligadas ao que cada um fez. Metade: divisão incompleta (duas ou três partes). Zero: sem divisão ou um só aluno fala.'),
      (v_atividade, 6, 3, 'Explique por que é importante que cada integrante explique a parte em que atuou.', 0.4, 'Porque mostra que todos participaram e entendem o projeto, valoriza o trabalho de cada um e deixa a apresentação mais completa e confiável.', 'Nota cheia: cita participação e domínio do projeto por todos. Metade: justificativa vaga. Zero: sem relação.'),
      (v_atividade, 7, 1, 'Cite as três tecnologias de impressão estudadas e explique como a impressora funciona, usando fatiamento, extrusão e camadas.', 0.3, 'FDM, SLA e SLS. A impressora recebe o modelo, o fatiador o corta em camadas e a impressora constrói a peça camada por camada (na FDM, por extrusão do material).', 'Nota cheia: as três tecnologias e a explicação com fatiamento, extrusão e camadas. Metade: as tecnologias ou a explicação, mas não os dois. Zero: sem relação.'),
      (v_atividade, 7, 2, 'Relacione a modelagem 3D e o design para impressão com a peça que a equipe criou.', 0.3, 'A modelagem 3D (Tinkercad, Fusion 360, Blender ou SketchUp) cria a forma da peça, e o design para impressão (espessura de paredes, suportes e orientação) garante que ela seja impressa e resista ao uso no robô.', 'Nota cheia: relaciona modelagem e design com a peça da equipe. Metade: só um dos dois. Zero: sem relação.'),
      (v_atividade, 7, 3, 'Explique como os componentes e a programação do robô, junto com o tipo de robô, se conectam à peça impressa, mostrando como design, engenharia e programação trabalham juntos.', 0.4, 'A peça impressa se fixa ou apoia o robô (sensores, atuadores, motores e controlador); a programação faz o robô agir; o tipo de robô define o uso. Design, engenharia e programação trabalham juntos para o protótipo funcionar.', 'Nota cheia: liga a peça aos componentes, cita a programação e conclui que design, engenharia e programação se unem. Metade: liga a peça ao robô sem a conclusão. Zero: sem relação.'),
      (v_atividade, 8, 1, 'Escreva o ponto forte da apresentação, de forma específica e respeitosa.', 0.3, 'Exemplo: "A equipe explicou o problema do robô de forma muito clara, e deu para entender por que a peça impressa foi necessária."', 'Nota cheia: ponto forte específico (a clareza do problema) em tom respeitoso. Metade: elogio genérico ("gostei"). Zero: sem elogio ou ofensivo.'),
      (v_atividade, 8, 2, 'Escreva a sugestão, de forma que ajude a equipe a melhorar sem criticar as pessoas.', 0.3, 'Exemplo: "Na próxima versão, vocês poderiam explicar o que melhorariam no robô e na peça, como uma parede mais grossa ou um sensor melhor."', 'Nota cheia: sugere falar das melhorias, de forma respeitosa e útil. Metade: sugestão vaga. Zero: sem sugestão ou crítica às pessoas.'),
      (v_atividade, 8, 3, 'Escreva uma autoavaliação de duas ou três frases sobre a sua participação no projeto, dizendo o que você fez bem e o que melhoraria.', 0.4, 'Resposta pessoal de duas ou três frases dizendo o que o aluno fez bem no projeto e o que melhoraria.', 'Nota cheia: cita o que fez bem e o que melhoraria. Metade: só um. Zero: em branco ou sem relação com o projeto.'),
      (v_atividade, 9, 1, 'Liste os quatro critérios da avaliação final com o peso de cada um.', 0.3, 'Testes/provas 35%; Projetos 40%; Participação 15%; Autoavaliação 10%.', 'Nota cheia: os quatro critérios com os pesos certos. Metade: os quatro critérios com um ou dois pesos errados, ou só dois certos. Zero: menos que isso.'),
      (v_atividade, 9, 2, 'Calcule a nota final desse aluno, mostrando a conta de cada critério.', 0.3, '8 × 0,35 = 2,8; 7 × 0,40 = 2,8; 10 × 0,15 = 1,5; 9 × 0,10 = 0,9. Soma: 8,0.', 'Nota cheia: conta de cada critério e nota final 8,0. Metade: método certo com erro de conta. Zero: método errado ou em branco.'),
      (v_atividade, 9, 3, 'Diga as quatro faixas da rúbrica de desempenho com as notas de cada uma e informe a nota mínima e a frequência mínima da última aula.', 0.4, 'Excelente (9–10), Bom (7–8), Aceitável (5–6) e Insuficiente (0–4). Nota mínima 7,0 e frequência mínima de 75%.', 'Nota cheia: quatro faixas com as notas e os dois mínimos. Metade: as faixas ou os mínimos, mas não os dois. Zero: sem relação.'),
      (v_atividade, 10, 1, 'Escreva a abertura da sua apresentação, em três ou quatro frases, apresentando o problema e a solução do protótipo.', 0.3, 'Resposta pessoal de três ou quatro frases que diga qual problema o robô resolve e como a peça impressa ajuda a resolvê-lo.', 'Nota cheia: problema e solução claros. Metade: só um. Zero: sem relação com o protótipo.'),
      (v_atividade, 10, 2, 'Diga o que os gestores avaliam para decidir se uma ideia segue adiante e como a sua equipe mostraria isso na demonstração.', 0.3, 'Os gestores avaliam a clareza do problema, a demonstração e os resultados medidos. A equipe mostraria isso explicando o problema, demonstrando o protótipo funcionando e apresentando resultados (por exemplo, testes realizados).', 'Nota cheia: cita pelo menos dois dos três critérios e como mostrar na demonstração. Metade: cita critérios sem ligar à demonstração. Zero: sem relação.'),
      (v_atividade, 10, 3, 'Proponha duas melhorias para a próxima versão do protótipo e justifique cada uma.', 0.4, 'Resposta pessoal com duas melhorias coerentes (por exemplo, ajustar a espessura das paredes, reduzir o uso de suportes, melhorar o programa ou trocar um sensor), cada uma com justificativa.', 'Nota cheia: duas melhorias coerentes justificadas. Metade: uma justificada, ou duas sem justificativa. Zero: nenhuma coerente.');
end $$;
